with filtered as (select *, case when category = 'Books' then 1 else 0 end as is_books, coalesce(brand, 'DIRECT') as brand_filled from products where launch_date >= date '2024-02-22' and cost < 660) select supplier_id, case when stock_qty >= 380 then 'LARGE' else 'SMALL' end as stock_qty_tier, count(*) as row_count, count(*) filter (where category = 'Electronics') as electronics_rows from filtered group by supplier_id, case when stock_qty >= 380 then 'LARGE' else 'SMALL' end order by supplier_id asc;
